/**
 * @name Cybercore Aero Y2K1
 * @author Cybercore Y2K1
 * @version 8.0.0
 * @description Native Cybercore Y2K1 Aero theme for Vesktop / Discord. Complete visual coverage with custom cyberpunk background, dark glass blur, neon violet and electric cyan styling across chats, channels, settings, and profile popouts.
 * @source https://github.com/Shules/cybercore-y2k1
 */

@import url('https://fonts.googleapis.com/css2?family=Exo+2:wght@300;400;500;600;700&family=Share+Tech+Mono&display=swap');

:root {
  --cyber-bg: #0E0918;
  --cyber-bg-alt: #140C22;
  --cyber-violet: #BD00FF;
  --cyber-violet-dim: rgba(189, 0, 255, 0.35);
  --cyber-cyan: #00F0FF;
  --cyber-cyan-dim: rgba(0, 240, 255, 0.25);
  --cyber-text: #E2E8F0;
  --cyber-text-dim: #9D8CB6;
  --cyber-text-bright: #FFFFFF;
  --font-primary: 'Exo 2', sans-serif !important;
}

/* 1. Guaranteed Fullscreen Backdrop */
#app-mount {
  background: transparent !important;
}

body {
  background: transparent !important;
}

body::before {
  content: "" !important;
  position: fixed !important;
  inset: 0 !important;
  background: url('data:image/png;base64,') center/cover no-repeat fixed !important;
  z-index: -2 !important;
}

body::after {
  content: "" !important;
  position: fixed !important;
  inset: 0 !important;
  background: linear-gradient(135deg, rgba(14, 9, 24, 0.52) 0%, rgba(20, 10, 32, 0.48) 100%) !important;
  backdrop-filter: blur(8px) saturate(125%) !important;
  z-index: -1 !important;
  pointer-events: none !important;
}

/* Clear all opaque wrappers */
.theme-dark,
[class*="app_"],
[class*="layers_"],
[class*="layer_"],
[class*="base_"],
[class*="chat_"],
[class*="chatContent_"],
[class*="messagesWrapper_"],
[class*="container_"][class*="fixClipping_"],
[class*="bg_"] {
  background: transparent !important;
}

/* 2. Sidebars */
nav[class*="guilds_"] {
  background: rgba(10, 6, 18, 0.65) !important;
  backdrop-filter: blur(14px) !important;
  border-right: 1px solid var(--cyber-violet-dim) !important;
}

div[class*="sidebar_"] {
  background: rgba(17, 10, 28, 0.60) !important;
  backdrop-filter: blur(10px) !important;
  border-right: 1px solid var(--cyber-violet-dim) !important;
}

[class*="channel_"] [class*="content_"] {
  border-radius: 4px !important;
  border-left: 2px solid transparent !important;
}

[class*="channel_"]:hover [class*="content_"] {
  background: rgba(0, 240, 255, 0.12) !important;
  border-left-color: var(--cyber-cyan) !important;
}

[class*="channel_"][class*="selected_"] [class*="content_"] {
  background: linear-gradient(90deg, rgba(189, 0, 255, 0.35) 0%, rgba(20, 12, 33, 0.5) 100%) !important;
  border-left: 2px solid var(--cyber-cyan) !important;
}

/* 3. Chat and Messages */
[class*="message_"]:hover {
  background: rgba(189, 0, 255, 0.10) !important;
}

[class*="mentioned_"] {
  background: rgba(189, 0, 255, 0.22) !important;
  border-left: 3px solid var(--cyber-cyan) !important;
}

[class*="mention"] {
  background: rgba(0, 240, 255, 0.18) !important;
  color: var(--cyber-cyan) !important;
  border: 1px solid var(--cyber-cyan) !important;
  border-radius: 3px !important;
}

[class*="channelTextArea_"] {
  background: rgba(22, 14, 38, 0.65) !important;
  border: 1px solid var(--cyber-violet-dim) !important;
  border-radius: 4px !important;
}

[class*="channelTextArea_"]:focus-within {
  border-color: var(--cyber-cyan) !important;
  box-shadow: 0 0 12px var(--cyber-cyan-dim) !important;
}

/* 4. Complete Settings Window (Dark Violet Solid Glass) */
[class*="standardSidebarView_"] {
  background: rgba(14, 9, 24, 0.90) !important;
  backdrop-filter: blur(16px) !important;
}

[class*="sidebarRegion_"] {
  background: rgba(17, 10, 28, 0.95) !important;
  border-right: 1px solid var(--cyber-violet-dim) !important;
}

[class*="sidebarRegion_"] [class*="item_"] {
  border-radius: 4px !important;
}

[class*="sidebarRegion_"] [class*="item_"]:hover {
  background: rgba(0, 240, 255, 0.12) !important;
  color: var(--cyber-cyan) !important;
}

[class*="sidebarRegion_"] [class*="selected_"][class*="item_"] {
  background: linear-gradient(90deg, rgba(189, 0, 255, 0.4) 0%, rgba(20, 12, 33, 0.7) 100%) !important;
  color: #FFFFFF !important;
  border-left: 3px solid var(--cyber-cyan) !important;
}

[class*="contentRegion_"] {
  background: rgba(14, 9, 24, 0.90) !important;
}

[class*="accountProfileCard_"],
[class*="card_"] {
  background: rgba(26, 16, 44, 0.8) !important;
  border: 1px solid var(--cyber-violet-dim) !important;
  border-radius: 6px !important;
}

/* 5. Complete Profile Popout Card (Dark Violet Glass & Cybercore Accents) */
[class*="userProfileModalOuter_"],
[class*="userPopoutOuter_"],
[class*="userProfileModalInner_"],
[class*="userPopoutInner_"] {
  background: #140C22 !important;
  border: 1px solid var(--cyber-violet) !important;
  border-radius: 6px !important;
  box-shadow: 0 10px 32px rgba(0, 0, 0, 0.9), 0 0 14px var(--cyber-violet-dim) !important;
}

[class*="userPopoutOuter_"] [class*="overlayBackground_"],
[class*="userProfileModalOuter_"] [class*="overlayBackground_"] {
  background: #1A102C !important;
  border: 1px solid rgba(189, 0, 255, 0.3) !important;
  border-radius: 4px !important;
}

/* Profile Header Colors */
[class*="userPopoutOuter_"] [class*="banner_"] {
  border-bottom: 1px solid var(--cyber-violet-dim) !important;
}

/* 6. Modals, Menus and Buttons */
[role="menu"],
[class*="menu_"],
[class*="modal_"] {
  background: #140C22 !important;
  border: 1px solid var(--cyber-violet) !important;
  border-radius: 6px !important;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.85) !important;
}

button[class*="button_"]:not([class*="lookBlank_"]) {
  border-radius: 4px !important;
}

button[class*="lookFilled_"][class*="colorBrand_"] {
  background: linear-gradient(135deg, #A200FF 0%, #BD00FF 100%) !important;
  border: 1px solid var(--cyber-violet) !important;
}

button[class*="lookFilled_"][class*="colorBrand_"]:hover {
  background: linear-gradient(135deg, #BD00FF 0%, #00F0FF 100%) !important;
  color: #0E0918 !important;
}

/* 7. Scrollbars */
::-webkit-scrollbar {
  width: 5px !important;
  height: 5px !important;
}

::-webkit-scrollbar-track {
  background: transparent !important;
}

::-webkit-scrollbar-thumb {
  background: rgba(189, 0, 255, 0.35) !important;
  border-radius: 3px !important;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--cyber-cyan) !important;
}
